import { useEffect, useRef, useState } from "react";
import * as THREE from "three";
import { OrbitControls } from "three/examples/jsm/controls/OrbitControls.js";
import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
import { RotateCcw } from "lucide-react";

/**
 * Respiratory viewer built on a real anatomical 3D model (embedded below as base64, simplified from an NIH 3D Visible Human respiratory model, so this is the only file you need).
 * The model is a single mesh, so labels are numbered markers placed by hand on its surface.
 * `p` is in the model's own coordinates: x = back→front, y = up, z = patient's left(−)→right(+).
 * side "f" = visible from the front, "b" = from the back. Check the labels against a textbook.
 */
type Part = { id: string; name: string; fn: string; color: string; p: [number, number, number]; side: "f" | "b"; xr?: boolean };

const PARTS: Part[] = [
  { id: "larynx", name: "Larynx (voice box)", fn: "Cartilage box at the top of the airway that holds the vocal cords and guards the entrance to the trachea.", color: "#e6c36a", p: [-0.052, 4.594, -0.085], side: "f" },
  { id: "trachea", name: "Trachea (windpipe)", fn: "Tube about 11 cm long, kept open by C-shaped rings of cartilage. Carries air between the larynx and the bronchi.", color: "#e6c36a", p: [0.04, 2.562, -0.028], side: "f" },
  { id: "carina", name: "Carina", fn: "Ridge where the trachea splits into the right and left main bronchi.", color: "#e6c36a", p: [-0.032, -0.133, 0.764], side: "f" },
  { id: "rbr", name: "Right main bronchus (X-ray)", fn: "Shorter, wider and more vertical than the left one.", color: "#e6c36a", p: [-0.525, -0.398, 0.624], side: "f", xr: true },
  { id: "lbr", name: "Left main bronchus (X-ray)", fn: "Longer and narrower than the right one, and runs more horizontally.", color: "#e6c36a", p: [0.96, -0.821, 0.544], side: "f", xr: true },
  { id: "rtree", name: "Bronchial tree, right lung (X-ray)", fn: "Bronchi keep dividing into smaller bronchioles that end in tiny air sacs (alveoli), where gas exchange happens.", color: "#e6c36a", p: [-1.922, -0.935, 0.222], side: "f", xr: true },
  { id: "ltree", name: "Bronchial tree, left lung (X-ray)", fn: "The same branching pattern in the left lung, ending in alveoli where oxygen enters the blood.", color: "#e6c36a", p: [1.438, -1.492, 0.184], side: "f", xr: true },
  { id: "rapex", name: "Apex of the right lung", fn: "The rounded top of the lung, reaching just above the first rib.", color: "#f08aa0", p: [-0.968, 2.018, 1.552], side: "f" },
  { id: "lapex", name: "Apex of the left lung", fn: "The rounded top of the left lung.", color: "#f08aa0", p: [1.381, 2.013, 1.571], side: "f" },
  { id: "rsup", name: "Right lung: superior lobe", fn: "The right lung has three lobes. The superior (upper) lobe lies above the horizontal fissure.", color: "#f08aa0", p: [-2.563, 1.253, 1.593], side: "f" },
  { id: "hfis", name: "Horizontal fissure", fn: "Groove in the right lung that separates the superior lobe from the middle lobe.", color: "#f08aa0", p: [-1.802, 0.295, 2.524], side: "f" },
  { id: "lsup", name: "Left lung: superior lobe", fn: "The left lung has two lobes and is a little smaller than the right to make room for the heart.", color: "#f08aa0", p: [2.422, 1.183, 2.163], side: "f" },
  { id: "rbase", name: "Base of the right lung", fn: "The lower surface rests on the diaphragm, the muscle that drives breathing.", color: "#f08aa0", p: [-2.06, -4.196, 2.639], side: "f" },
  { id: "lbase", name: "Base of the left lung", fn: "The lower surface rests on the diaphragm.", color: "#f08aa0", p: [1.994, -4.484, 2.625], side: "f" },
  { id: "rinf", name: "Right lung: inferior lobe (back view)", fn: "Lies below and behind the oblique fissure.", color: "#f08aa0", p: [-1.373, -2.173, -2.732], side: "b" },
  { id: "linf", name: "Left lung: inferior lobe (back view)", fn: "Lies below and behind the oblique fissure that divides the left lung.", color: "#f08aa0", p: [2.107, -2.334, -2.55], side: "b" },
];

const SCALE = 1;

export default function RespiratoryModelViewer({ label, blurb }: { label: string; blurb: string; theme: "dark" | "light" }) {
  const holder = useRef<HTMLDivElement>(null);
  const dots = useRef<Record<string, HTMLButtonElement | null>>({});
  const ctl = useRef({ auto: true, infl: 0.35, rate: 14, xray: false, fly: null as THREE.Vector3 | null, loaded: false, cam: null as THREE.PerspectiveCamera | null, controls: null as OrbitControls | null });
  const [pin, setPin] = useState<string | null>(null);
  const [xray, setXray] = useState(false);
  const [all, setAll] = useState(false);
  const [auto, setAuto] = useState(true);
  const [infl, setInfl] = useState(0.35);
  const [rate, setRate] = useState(14);
  const [ready, setReady] = useState(false);
  const [failed, setFailed] = useState(false);
  const mats = useRef<THREE.Material[]>([]);

  useEffect(() => {
    const el = holder.current;
    if (!el) return;
    const c = ctl.current;
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    el.appendChild(renderer.domElement);
    const scene = new THREE.Scene();
    const cam = new THREE.PerspectiveCamera(35, 1, 0.1, 100);
    cam.position.set(0, 0.6, 24);
    c.cam = cam;
    const controls = new OrbitControls(cam, renderer.domElement);
    controls.enableDamping = true;
    controls.enablePan = false;
    controls.minDistance = 8;
    controls.maxDistance = 45;
    c.controls = controls;
    scene.add(new THREE.HemisphereLight(0xffffff, 0x556688, 1.6));
    const d1 = new THREE.DirectionalLight(0xffffff, 1.4);
    d1.position.set(6, 6, 4);
    scene.add(d1);
    const d2 = new THREE.DirectionalLight(0xffffff, 0.8);
    d2.position.set(-6, 2, -5);
    scene.add(d2);
    const group = new THREE.Group();
    group.scale.setScalar(SCALE);
    scene.add(group);
    let disposed = false;
    const raw = atob(MODEL_B64);
    const bytes = new Uint8Array(raw.length);
    for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
    new GLTFLoader().parse(
      bytes.buffer as ArrayBuffer,
      "",
      (g) => {
        if (disposed) return;
        group.add(g.scene);
        g.scene.traverse((o) => {
          const m = (o as THREE.Mesh).material as THREE.Material | undefined;
          if (m) mats.current.push(m);
        });
        c.loaded = true;
        setReady(true);
      },
      () => setFailed(true),
    );
    const resize = () => {
      renderer.setSize(el.clientWidth, el.clientHeight);
      cam.aspect = el.clientWidth / Math.max(el.clientHeight, 1);
      cam.updateProjectionMatrix();
    };
    const ro = new ResizeObserver(resize);
    ro.observe(el);
    resize();
    const still = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const t0 = performance.now();
    const v = new THREE.Vector3();
    let raf = 0;
    const loop = () => {
      raf = requestAnimationFrame(loop);
      const tt = (performance.now() - t0) / 1000;
      const inflation = c.auto ? (still ? 0.5 : 0.5 - 0.5 * Math.cos((2 * Math.PI * c.rate * tt) / 60)) : c.infl;
      group.scale.set(SCALE * (1 + 0.05 * inflation), SCALE * (1 + 0.025 * inflation), SCALE * (1 + 0.05 * inflation));
      if (c.fly) {
        cam.position.lerp(c.fly, 0.12);
        if (cam.position.distanceTo(c.fly) < 0.05) c.fly = null;
      }
      controls.update();
      group.updateMatrixWorld();
      const cx = cam.position.clone().normalize().z;
      const w = el.clientWidth;
      const h = el.clientHeight;
      PARTS.forEach((a) => {
        const d = dots.current[a.id];
        if (!d) return;
        const visible = c.loaded && (!a.xr || c.xray) && (a.side === "f" ? cx > 0.1 : cx < -0.1);
        d.style.display = visible ? "block" : "none";
        if (!visible) return;
        v.set(...a.p);
        group.localToWorld(v);
        v.project(cam);
        d.style.transform = `translate(${((v.x + 1) / 2) * w}px, ${((1 - v.y) / 2) * h}px)`;
      });
      renderer.render(scene, cam);
    };
    loop();
    return () => {
      disposed = true;
      cancelAnimationFrame(raf);
      ro.disconnect();
      controls.dispose();
      scene.traverse((o) => {
        const m = o as THREE.Mesh;
        m.geometry?.dispose();
        const mat = m.material as THREE.MeshStandardMaterial | undefined;
        if (mat) {
          mat.map?.dispose();
          mat.normalMap?.dispose();
          mat.metalnessMap?.dispose();
          mat.dispose();
        }
      });
      mats.current = [];
      renderer.dispose();
      if (renderer.domElement.parentNode === el) el.removeChild(renderer.domElement);
    };
  }, []);

  useEffect(() => {
    ctl.current.xray = xray;
    mats.current.forEach((m) => {
      m.transparent = xray;
      m.opacity = xray ? 0.3 : 1;
      m.depthWrite = !xray;
      m.needsUpdate = true;
    });
  }, [xray, ready]);

  const side = (s: 1 | -1) => {
    const cam = ctl.current.cam;
    if (!cam) return;
    const d = cam.position.length();
    ctl.current.fly = new THREE.Vector3(0, d * 0.04, s * d * 0.99);
  };
  const fit = () => {
    ctl.current.fly = new THREE.Vector3(0, 0.6, 24);
    ctl.current.controls?.target.set(0, 0, 0);
  };
  const pick = (id: string) => {
    const next = pin === id ? null : id;
    setPin(next);
    const a = PARTS.find((p) => p.id === next);
    if (a?.xr && !xray) setXray(true);
    const cam = ctl.current.cam;
    if (a && cam) {
      const cx = cam.position.clone().normalize().z;
      if ((a.side === "f" && cx < 0.3) || (a.side === "b" && cx > -0.3)) side(a.side === "f" ? 1 : -1);
    }
  };
  const sel = PARTS.find((p) => p.id === pin);
  /* The stage, its header and the deck below are one dark instrument face in
     both themes — the model needs a black studio behind it, and a panel split
     between a black stage and a paper deck read as two different tools. The
     ink therefore stays light in light mode too; the page around the panel is
     what follows the theme. */
  const edge = "border-white/10";
  const txt = "text-slate-100";
  const sub = "text-slate-400";
  const btn = (on: boolean) =>
    `cursor-pointer rounded-lg border px-3 py-1.5 text-xs font-semibold transition-colors ${edge} ${on ? "bg-[#6f7cff] text-white" : `${txt} hover:bg-white/10`}`;

  return (
    <div className="lab-split">
      <div className="lab-stage-pane lab-glass p-2.5 sm:p-4">
        <div className="mb-2.5 flex items-center justify-between gap-2">
          <div className="min-w-0">
            <p className={`truncate text-sm font-bold ${txt}`}>{label}</p>
            <p className={`hidden text-[11px] sm:block ${sub}`}>{blurb}</p>
          </div>
          <button type="button" className={btn(false)} onClick={fit}>
            <RotateCcw className="mr-1 inline h-3 w-3" />
            Fit view
          </button>
        </div>
        <div className="lab-model-stage relative h-[58vh] min-h-[340px] overflow-hidden rounded-xl border border-white/10 bg-[#08080a]">
          <div ref={holder} className="absolute inset-0" />
          {!ready && !failed && <div className="absolute inset-0 grid place-items-center text-sm text-slate-400">Loading lung model…</div>}
          {failed && <div className="absolute inset-0 grid place-items-center px-6 text-center text-sm text-slate-400">Could not load the lung model.</div>}
          {PARTS.map((a, i) => (
            <button
              key={a.id}
              type="button"
              aria-label={a.name}
              ref={(el) => {
                dots.current[a.id] = el;
              }}
              onClick={() => pick(a.id)}
              style={{ background: a.color, display: "none" }}
              className={`organ-dot absolute left-0 top-0 -ml-3 -mt-3 h-6 w-6 cursor-pointer rounded-full border-2 border-white text-[11px] font-bold text-white shadow ${pin === a.id ? "z-10 scale-125" : ""}`}
            >
              {i + 1}
              {(all || pin === a.id) && <span className="absolute left-7 top-0.5 whitespace-nowrap rounded-md bg-black/90 px-2 py-0.5 text-xs">{a.name}</span>}
            </button>
          ))}
          <p className="pointer-events-none absolute bottom-2 right-3 hidden text-[10px] text-slate-400 sm:block">drag orbit · scroll zoom · tap a numbered dot</p>
        </div>
      </div>

      <div className="lab-deck-pane lab-glass-deep space-y-3 p-3.5">
        <div className="flex flex-wrap gap-2">
          <button type="button" className={btn(false)} onClick={() => side(1)}>Front</button>
          <button type="button" className={btn(false)} onClick={() => side(-1)}>Back</button>
          <button type="button" className={btn(xray)} onClick={() => setXray(!xray)}>X-ray</button>
          <button type="button" className={btn(all)} onClick={() => setAll(!all)}>All labels</button>
        </div>
        <div className={`space-y-2 text-xs ${sub}`}>
          <div className="flex items-center gap-2">
            <button type="button" className={btn(auto)} onClick={() => { setAuto(!auto); ctl.current.auto = !auto; }}>
              {auto ? "Auto breathing: on" : "Auto breathing: off"}
            </button>
            <span>Rate</span>
            <input type="range" min={8} max={30} value={rate} className="flex-1" onChange={(e) => { setRate(+e.target.value); ctl.current.rate = +e.target.value; }} />
            <b className={txt}>{rate}/min</b>
          </div>
          <label className="flex items-center gap-2">
            Lung inflation
            <input type="range" min={0} max={100} value={Math.round(infl * 100)} disabled={auto} className="flex-1" onChange={(e) => { setInfl(+e.target.value / 100); ctl.current.infl = +e.target.value / 100; }} />
            <b className={txt}>{auto ? "auto" : `${Math.round(infl * 100)}%`}</b>
          </label>
          <p>A quiet breath moves about 500 mL of air.</p>
        </div>
        <div className={`min-h-20 rounded-xl border ${edge} p-3 text-xs leading-relaxed ${txt}`}>
          {sel ? (
            <>
              <b style={{ color: sel.color }}>{sel.name}</b>
              <br />
              {sel.fn}
            </>
          ) : (
            <span className={sub}>Select a part to see what it does.</span>
          )}
        </div>
        <div className="flex flex-col gap-1">
          {PARTS.map((a, i) => (
            <button
              key={a.id}
              type="button"
              onClick={() => pick(a.id)}
              className={`lab-part-row flex cursor-pointer items-center gap-2 rounded-lg border px-2 py-1 text-left text-xs ${edge} ${txt} ${pin === a.id ? "bg-white/10" : ""}`}
            >
              <i className="h-2.5 w-2.5 flex-none rounded-full" style={{ background: a.color }} />
              {i + 1}. {a.name}
            </button>
          ))}
        </div>
        <p className={`text-[10px] leading-relaxed ${sub}`}>Pink = lung tissue, tan = airway and bronchial tubes (turn on X-ray to see inside the lungs). Labels were placed by hand on one 3D model, so check them against your textbook.</p>
      </div>
    </div>
  );
}

// Embedded model data (about 2 MB). Do not edit by hand.
// prettier-ignore
const MODEL_B64 =
  "";
